import { enrollDevice } from '@projexlight/sdk-device';
const { device_uuid, enrollment_token } = await enrollDevice({
  tenant_id, persona_id, kind: 'tablet', model: 'iPad-12.9-2024',
  os_version: 'iOS-18.4', platform_id_blob,
});

import { runAttestation } from '@projexlight/sdk-device';
await runAttestation({
  device_uuid, platform_integrity_blob,
  os_version: 'iOS-18.4', patch_level: '2026-05',
});

// runAttestation logic:
if (!integrityValid) {
  await recordFailedAttestation({ device_uuid, reason: 'jailbreak-detected' });
  scheduleAutoRevoke({ device_uuid, grace_min: DEVICE_REVOKE_GRACE_MIN });
}

import { revokeTrust } from '@projexlight/sdk-device';
await revokeTrust({
  device_uuid, reason: 'reported-lost',
  operator_persona_id,
});

import { reassignDevice } from '@projexlight/sdk-device';
await reassignDevice({
  device_uuid, new_persona_id,
  reason: 'tech-transfer', operator_persona_id,
});
